	}
	mirror := plumbing.NewHashReference(refs.Mirror, primaryRef.Hash())
	if err := repo.Storer.SetReference(mirror); err != nil {
		return fmt.Errorf("set ref %s to %s: %w", refs.Mirror, primaryRef.Hash(), err)
	}
	return nil
}

